advancedQueries.query:
topk(20,
  sum by (
    kube_cluster_name,
    kube_namespace_name,
    kube_workload_type,
    kube_workload_name,
    kube_pod_name
  ) (
    rate(sysdig_container_net_error_count{
$__scope
    }[5m])
  )
)

sum by (target_cluster, probe_name) (
  count_over_time(
    probe_success{
      job=~"artifactory-blackbox-(ping|docker-v2)",
      target_cluster=~$cluster
    }[$__range]
  )
  -
  sum_over_time(
    probe_success{
      job=~"artifactory-blackbox-(ping|docker-v2)",
      target_cluster=~$cluster
    }[$__range]
  )
)
